import{_ as i,l as n,o as e,c as s,v as t,p as l,x as r,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"注入作为输入边界","description":"","frontmatter":{"title":"注入作为输入边界","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/injection-boundary.md","filePath":"cs/injection-boundary.md","lastUpdated":1789023840000}'),p={name:"cs/injection-boundary.md"};function E(A,a,_,u,B,m){const o=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="注入作为输入边界" tabindex="-1">注入作为输入边界 <a class="header-anchor" href="#注入作为输入边界" aria-label="Permalink to &quot;注入作为输入边界&quot;">​</a></h1><div class="epigraph"><p>不可信字节一旦被当成另一语言的语法来解释，完整性与授权就落在解释器里而不是落在你的程序里。</p><footer>—— 据 Saltzer 完整中介；Anderson 对注入类失败；对照参数化查询与类型化 API</footer></div><p><a href="/cs/same-origin-csrf">上一课</a>把浏览器代理人与意图分开。本课不重做 Cookie。缺口是更一般的边界：SQL、壳、HTML、模板都是解释器。把用户字符串拼进语句，等于让外人写程序。防御是参数与上下文编码，而不是「过滤几个字符」。本课是安全主干最后一课；下一课封口整个计算栈。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CSRF 是混淆代理人。注入是混淆语言：数据通道与控制通道合一。数据库课的 <a href="/cs/sql-declarative">SQL</a> 是语言；若查询字符串由拼接生成，完整性（谁被更新）与授权（哪一行）不再由参数决定。缺口是<strong>输入必须停在数据槽里</strong>。本课不提供任何可执行的注入语句或绕过清单。</p><p><span class="marginnote">参数化查询、ORM 的绑定、避免壳、模板自动转义，都是同一句话：先选解释器，再只传值。WAF 是补偿控制，不是规格。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>接口：占位符 + 绑定值；API 不暴露「拼完再 exec」。HTML：按上下文编码（元素 vs 属性），而不是同一套替换。最小特权：解释器用的账号不能是管理员。完整中介：每一次解释都经过绑定层。与 <a href="/cs/toctou">TOCTOU</a> 对照：都是判决没落在真正被解释的那份对象上。</p>',8)),(e(),l(h,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20UNTRUST%5B%22%E4%B8%8D%E5%8F%AF%E4%BF%A1%E8%BE%93%E5%85%A5%22%5D%20--%3E%20BIND%5B%22%E4%BD%9C%E4%B8%BA%E5%8F%82%E6%95%B0%E7%BB%91%E5%AE%9A%22%5D%0A%20%20BIND%20--%3E%20INT%5B%22%E8%A7%A3%E9%87%8A%E5%99%A8%E5%8F%AA%E8%A7%81%E5%80%BC%22%5D%0A%20%20CONCAT%5B%22%E6%8B%BC%E8%BF%9B%E8%AF%AD%E5%8F%A5%22%5D%20--%3E%20MIX%5B%22%E6%95%B0%E6%8D%AE%E5%8F%98%E6%88%90%E8%AF%AD%E6%B3%95%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>绑定把 DY 敌手能注入的「项」限制在值域，语句树由应用固定。这服务 CIA 的 I 与授权（E）。TLS 与同源不替代本课：信道可以很干净，拼出来的语句仍然是外人的程序。后课<a href="/cs/to-systems-boundary">计算栈到此为止</a> 不再补一种解释器。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把注入细类写成考试名单，不讨论绕过过滤器的技巧。计算机栏主干在下一课封口，不进入大模型或限价簿。</p><p>后课默认：不可信输入不得成为宿主语言。系统栈课程结束，附录只对照文献。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>注入是数据被当成语法；防御是绑定与分上下文编码。</li><li>与 CSRF 不同：这里是解释器边界，不是 Cookie 意图。</li><li>下一课封口本栏主干。</li><li>出处：Saltzer and Schroeder；Anderson；对照 Date/SQL 绑定实践。</li></ul>',7))])}const S=i(p,[["render",E]]);export{T as __pageData,S as default};
